-- Blackfathom Deeps: the redesigned layout (patch 6.0.2) next to the classic one.
--
-- HavenCore spawns the classic Blackfathom Deeps (Ghamoo-Ra, Lady Sarevess, Gelihast, Lorgus Jett,
-- Baron Aquanis, Twilight Lord Kelris, Old Serra'kis, Aku'mai). The 8.3.7 client's Adventure Guide
-- and the dungeon objectives (scenario 333) describe the redesign (Ghamoo-Ra, Domina, Subjugator
-- Kor'ul, Thruk, Guardian of the Deep, Executioner Gore, Twilight Lord Bathiel, Aku'mai the
-- Devourer). The database already had the redesign's creature templates, SmartAI, loot and quests,
-- but no spawns.
--
-- This adds the redesign's spawns, converted from TrinityCore master's sniffed layout
-- (sql/old/11.x/world/25031_2025_05_31/2025_04_22_00_world.sql): 280 creatures, 74 gameobjects,
-- 2 patrol paths, template addons and the entrance quest givers per faction. Guids 4800000-4800999.
-- Every redesign spawn is in spawn groups 433-440; tools/bfa/blackfathom-layouts.patch shows them
-- or the classic spawns (everything else on map 48 in the default spawn group) per instance.
--
-- Also adds the Blackfathom Chronicler (custom creature 4800000, spawn group 441, shown in both
-- layouts) at the entrance, who changes the layout until the first boss falls, and the
-- redesign bosses' dungeon encounters (DungeonEncounter ids from the client's JournalEncounter.db2).
--
-- Needs tools/bfa/blackfathom-layouts.patch; without it both layouts are visible at once.
-- Revert: run the DELETE lines below (they only touch guids 4800000-4800999, spawn groups 433-441,
-- creature 4800000 and the listed template rows), then the UPDATE lines at the bottom with the
-- values in their comments.
-- Safe to run twice. Restart worldserver afterwards.

-- Creatures (280)
DELETE FROM `creature` WHERE `map` = 48 AND `guid` BETWEEN 4800000 AND 4800999;

DELETE FROM `creature_addon` WHERE `guid` BETWEEN 4800000 AND 4800999;

-- Patrol paths (waypoint_data id = guid * 10)
DELETE FROM `waypoint_data` WHERE `id` BETWEEN 48000000 AND 48009999;

-- Gameobjects (74)
DELETE FROM `gameobject` WHERE `map` = 48 AND `guid` BETWEEN 4800000 AND 4800999;

DELETE FROM `gameobject_addon` WHERE `guid` BETWEEN 4800000 AND 4800999;

-- Spawn groups: the redesign layout, and its spawns shown only for one faction or after a boss
DELETE FROM `spawn_group_template` WHERE `groupId` BETWEEN 433 AND 440;

DELETE FROM `spawn_group` WHERE `groupId` BETWEEN 433 AND 440;

-- Template addons of redesign-only creatures
DELETE FROM `creature_template_addon` WHERE `entry` IN (75157, 75172, 75155, 75780, 75781, 75147, 74569, 75553, 75463, 75396, 75550, 75158, 75575, 74979, 76036, 75090, 75086, 74747, 74728, 74508, 76062, 75307, 74518, 76005, 75042, 75046, 75039, 74505, 74363, 75060, 75011, 75012, 74984, 75000, 75643, 75642, 75658, 74476, 74721, 74720, 75641, 75640, 74565, 74446, 76012, 74408, 75980, 75607);

-- Blackfathom Chronicler: picks the layout of the run (npc_blackfathom_chronicler)
DELETE FROM `creature_template` WHERE `entry` = 4800000;
DELETE FROM `creature_template_model` WHERE `CreatureID` = 4800000;
DELETE FROM `creature` WHERE `guid` = 4800999;
DELETE FROM `spawn_group_template` WHERE `groupId` = 441;
DELETE FROM `spawn_group` WHERE `groupId` = 441;

-- Redesign bosses as dungeon encounters (boss loot, boss frames, dungeon completion)
DELETE FROM `instance_encounters` WHERE `entry` IN (1667, 1668, 1669, 1670, 1671, 1672, 1675, 1676);

-- Entrance quest givers' weapons (TrinityCore sniff)
DELETE FROM `creature_equip_template` WHERE `ID` = 1 AND `CreatureID` IN (75607, 75606);

-- Rope Ladder Post can't be clicked (the rope next to it is the usable part)
DELETE FROM `gameobject_template_addon` WHERE `entry` = 224747;

UPDATE `creature_template` SET `gossip_menu_id` = 16166 WHERE `entry` = 75428; -- Frightened Prisoner, was 0
UPDATE `gameobject_template_addon` SET `WorldEffectID` = 569 WHERE `entry` = 225817; -- Spoils of Blackfathom, was 0
UPDATE `creature_template` SET `lootid` = 4829 WHERE `entry` = 75155; -- Aku'mai the Devourer had no loot (was 0); uses classic Aku'mai's table, as on retail
